import {serviceMessage} from './service-message.mjs';
import {billingQuoteLabel} from './billing-notice.mjs';
import {validServiceQuote} from './thesis-online.mjs';
import {readingWorkflowMarkup,updateReadingWorkflow,bindReadingWorkflow,focusReadingTarget} from './literature-workflow.mjs';
import {esc,icon} from './ui.mjs';
import {reuseStoredOriginal} from './file-selection.mjs';
import {createDocumentServiceClient,watchDocumentService,fileBase64,documentServiceLoginHref} from './document-services-client.mjs';
const languageNames={zh:'中文',en:'英语'},statusNames={queued:'排队中',pending:'排队中',running:'翻译中',completed:'已完成',failed:'未完成',cancelled:'已取消'},terminal=status=>['completed','failed','cancelled'].includes(status);
export function eligibleTranslationFiles(files){return (Array.isArray(files)?files:[]).filter(file=>file&&typeof file.id==='string'&&/\.(pdf|docx)$/i.test(file.name||'')&&file.deletionStatus!=='pending');}
export function validateTranslationFile(file,cap={}){if(!file||!/\.(pdf|docx)$/i.test(file.name||''))throw Error('请选择 PDF 或 DOCX 文件；旧版 DOC 请先另存为 DOCX。');const max=Math.min(Number(cap.maxFileBytes)||10*1024*1024,/\.docx$/i.test(file.name)?2*1024*1024:10*1024*1024);if(!file.size||file.size>max)throw Error(`${/\.docx$/i.test(file.name)?'DOCX':'PDF'} 文件最大 ${Math.floor(max/1024/1024)}MB，请压缩或拆分后上传。`);return max;}
export function translationDownloadPath(value){if(typeof value!=='string'||!value.startsWith('/api/')||value.startsWith('//')||/[\\\r\n]/.test(value))return '';try{const url=new URL(value,'https://paperknow.cn');return url.origin==='https://paperknow.cn'&&url.pathname.startsWith('/api/artifacts/')&&!url.search?url.pathname:'';}catch{return '';}}
export function mountDocumentTranslation({container,notify=()=>{},fetchImpl,uuid=()=>crypto.randomUUID(),pollInterval=4000}={}){
 let viewingSelected=false,submitting=false,flowError='',flowMessage='',errorStep=1,jobsSignature='',selectedSignature='';let alive=true,session=null,cap={},files=[],jobs=[],selected=null,busy=false,timer=null,unwatch=()=>{},requestKey=uuid(),uploaded=null,operation=0,preparedQuote=null,quoteInput='',quoteVersion=0,quoteExpiry=null;const $=s=>container.querySelector(s),current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});
 const dispose=()=>{if(!alive)return;alive=false;operation++;clearTimeout(timer);clearTimeout(quoteExpiry);client.dispose();unwatch();};unwatch=watchDocumentService(container,dispose);
 const state=(text,error=false)=>{const node=$('[data-doc-translation-status]');if(node){node.textContent=text;node.classList.toggle('is-error',error);}flowMessage=text;flowError=error?text:'';updateWorkflow();};
 function setBusy(value){busy=value;container.setAttribute('aria-busy',String(value));container.querySelectorAll('[data-doc-translation-form] input,[data-doc-translation-form] select,[data-doc-translation-form] button,[data-doc-translation-refresh],[data-doc-translation-open]').forEach(node=>node.disabled=value);updateWorkflow();}
 function updateWorkflow(){
  const nav=$('[data-reading-workflow]');if(!nav)return;const hasFile=!!$('[data-doc-file]')?.value||!!$('[data-doc-upload]')?.files?.[0];let step=hasFile?2:1,phase=hasFile?'review':'prepare',hint=hasFile?'核对原文语言、目标语言与文档处理说明，再开始翻译。':'上传 PDF / DOCX，或从已有文件中选择原件。';
  if(submitting){step=3;phase='submitting';hint=flowMessage||'正在核对文档并提交翻译，请稍候，无需重复点击。';}
  else if(flowError){step=errorStep;phase='failed';hint=flowError;}
  else if(viewingSelected&&selected){step=3;phase=selected.status;hint=selected.status==='queued'||selected.status==='pending'?'翻译任务已提交，正在等待处理；进度会自动更新。':selected.status==='running'?'正在翻译文档，结果会自动更新；离开页面不会取消任务。':selected.status==='cancelled'?'翻译已停止，原件与任务记录仍保留。':selected.status==='failed'?'本次翻译未完成，请查看下方原因；原件仍保留。':'任务已结束，译文文件仍待确认。';if(selected.status==='completed'){const downloadable=(selected.result?.artifacts||[]).some(file=>translationDownloadPath(file.downloadUrl));if(downloadable){step=4;phase='complete';hint='译文 Word 已准备好，可下载后对照原件核对术语、数字与排版。';}else{phase='result_unavailable';hint='任务已结束，但当前没有可下载的译文文件，请查看任务详情或刷新记录。';}}}
  updateReadingWorkflow(nav,{step,phase,hint,disabled:[...(!hasFile&&!viewingSelected?[2,3]:[]),...(step!==4?[4]:[])]});
 }
 function changed(){clearTimeout(quoteExpiry);quoteVersion++;preparedQuote=null;quoteInput='';viewingSelected=false;flowError='';flowMessage='';updateWorkflow();void prepareQuote();}
 function render(){if(!current())return;jobsSignature='';selectedSignature='';container.innerHTML=`<section class="document-service document-translation"><div class="document-service-intro"><span class="document-service-icon">${icon('language',23)}</span><div><h3>翻译整篇文档，保留可编辑的结果</h3><p>中文与英语互译 · PDF / DOCX → Word</p></div></div><p class="document-service-note">尽量保留原文布局；PDF 将译为可编辑 Word。扫描件、复杂表格和公式可能需要进一步核对，不保证与原件逐像素一致。</p>${readingWorkflowMarkup('document')}<form data-doc-translation-form data-unprotected><div class="document-service-fields"><label>原文语言<select data-doc-source><option value="en">英语</option><option value="zh">中文</option></select></label><label>翻译成<select data-doc-target><option value="zh">中文</option><option value="en">英语</option></select></label></div><label class="document-service-field">选择账户原件<select data-doc-file><option value="">上传新文档</option>${files.map(file=>`<option value="${esc(file.id)}">${esc(file.name)} · ${Math.ceil(Number(file.bytes||0)/1024)} KB</option>`).join('')}</select></label><label class="document-service-upload" data-doc-upload-wrap>${icon('upload',23)}<b>选择 PDF 或 DOCX 原件</b><span>PDF 最大 10MB / ${Math.min(Number(cap.maxPages)||100,100)} 页；DOCX 最大 2MB</span><input type="file" data-doc-upload accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" aria-label="选择待翻译文档"><small data-doc-upload-name>选择后保存到文件管理，以核对本次费用</small></label><p class="document-service-note">选择文件即表示你有权使用该文档，文件将保存至文件管理并用于翻译。</p><div class="document-service-actions"><button type="submit" class="btn primary">${icon('language',16)} 开始整篇翻译</button><span data-doc-billing role="status">选择文件后显示本次费用。</span></div></form><p class="document-service-status" data-doc-translation-status role="status" aria-live="polite">请核对原文语言后提交。离开页面不会取消已提交的翻译。</p><section class="document-service-tasks"><header><h3>我的文档翻译</h3><button class="btn secondary" type="button" data-doc-translation-refresh>刷新任务</button></header><div data-doc-translation-jobs></div><div data-doc-translation-detail></div></section></section>`;bindReadingWorkflow($('[data-reading-workflow]'),step=>focusReadingTarget($(step===1?'[data-doc-file]':step===2?'[data-doc-source]':step===3?'[data-doc-translation-status]':'[data-doc-translation-detail]')));renderJobs();updateWorkflow();
 $('[data-doc-file]').onchange=()=>{$('[data-doc-upload-wrap]').hidden=!!$('[data-doc-file]').value;uploaded=null;requestKey=uuid();changed();};$('[data-doc-upload]').onchange=()=>{$('[data-doc-file]').value='';$('[data-doc-upload-wrap]').hidden=false;const file=$('[data-doc-upload]').files?.[0];$('[data-doc-upload-name]').textContent=file?file.name:'文件仅在确认提交后上传';uploaded=null;requestKey=uuid();changed();};$('[data-doc-source]').onchange=()=>{$('[data-doc-target]').value=$('[data-doc-source]').value==='en'?'zh':'en';requestKey=uuid();changed();};$('[data-doc-target]').onchange=()=>{requestKey=uuid();changed();};$('[data-doc-translation-form]').onsubmit=event=>{event.preventDefault();void submit();};$('[data-doc-translation-refresh]').onclick=()=>void refresh();
 }
 function renderJobs(){if(!current())return;const node=$('[data-doc-translation-jobs]');if(!node)return;const signature=JSON.stringify([jobs.map(({id,fileName,sourceLanguage,targetLanguage,status})=>({id,fileName,sourceLanguage,targetLanguage,status})),selected?.id]);if(signature===jobsSignature)return;jobsSignature=signature;node.innerHTML=jobs.length?jobs.map(job=>`<button type="button" class="document-service-task ${selected?.id===job.id?'active':''}" data-doc-translation-open="${esc(job.id)}"><span>${icon('file',18)}<b>${esc(job.fileName||'文档翻译')}</b><small>${esc(languageNames[job.sourceLanguage]||job.sourceLanguage||'')} → ${esc(languageNames[job.targetLanguage]||job.targetLanguage||'')}</small></span><em class="${job.status==='completed'?'is-success':''}">${esc(statusNames[job.status]||'处理中')} →</em></button>`).join(''):'<p class="document-service-empty">提交后，翻译进度和可下载结果会保留在这里。</p>';node.querySelectorAll('[data-doc-translation-open]').forEach(button=>button.onclick=()=>{if(!busy)void openJob(button.dataset.docTranslationOpen);});}
 function renderSelected(){if(!selected||!current())return;const job=selected,result=job.result,artifacts=Array.isArray(result?.artifacts)?result.artifacts:[];const output=$('[data-doc-translation-detail]');const signature=JSON.stringify(job);if(signature===selectedSignature&&output.firstElementChild){updateWorkflow();return;}selectedSignature=signature;output.innerHTML=`<article class="document-service-result"><header><div><span>${job.status==='completed'?'翻译已完成':'文档翻译进度'}</span><h4>${esc(job.fileName||'文档翻译')}</h4></div><b class="${job.status==='completed'?'is-success':''}">${esc(statusNames[job.status]||'处理中')}</b></header><p>${esc(languageNames[job.sourceLanguage]||job.sourceLanguage)} → ${esc(languageNames[job.targetLanguage]||job.targetLanguage)}${Number(job.pageCount||result?.pageCount)?' · '+Number(job.pageCount||result.pageCount)+' 页':''}</p>${job.status==='failed'?`<p class="is-error" role="alert">${esc(serviceMessage(typeof job.error==='string'?job.error:job.error?.message||'翻译未完成，请稍后重试或更换文档。'))}</p>`:job.status==='cancelled'?'<p>处理已停止，原文仍保留在账户中。</p>':!terminal(job.status)?'<p>文档正在云端处理。你可以离开，稍后回到“文献翻译”查看，不需要重复上传。</p>':'<p>下载后请核对专业术语、数字、图表、公式与排版。</p>'}<div class="document-service-actions">${artifacts.map(file=>{const path=translationDownloadPath(file.downloadUrl);return path?`<a class="btn primary" href="${esc(path)}">${icon('download',16)} 下载译文 Word</a>`:'';}).join('')}${!terminal(job.status)?'<button type="button" class="btn secondary" data-doc-translation-cancel>取消本站任务</button>':''}</div>${Array.isArray(result?.warnings)&&result.warnings.length?`<ul>${result.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</article>`;const cancel=$('[data-doc-translation-cancel]');if(cancel)cancel.onclick=async()=>{cancel.disabled=true;try{await client.request('/document-translations/'+encodeURIComponent(job.id)+'/cancel',{});await openJob(job.id);}catch(error){if(current()&&error.name!=='AbortError'){state(error.message,true);cancel.disabled=false;}}};updateWorkflow();}
 function schedule(){clearTimeout(timer);if(selected&&!terminal(selected.status)&&current())timer=setTimeout(()=>void openJob(selected.id,true),pollInterval);}
 async function openJob(id,poll=false){if(!poll)viewingSelected=true;errorStep=3;clearTimeout(timer);const ticket=++operation;try{const job=await client.request('/document-translations/'+encodeURIComponent(id));if(!current()||ticket!==operation)return;selected=job;jobs=[job,...jobs.filter(item=>item.id!==job.id)].slice(0,20);renderJobs();renderSelected();if(!poll)state('已读取任务进度。');schedule();}catch(error){if(current()&&ticket===operation&&error.name!=='AbortError'){state(error.status===401?'登录已失效，请重新登录后查看任务。':error.message,true);if(poll&&error.status!==401)timer=setTimeout(()=>void openJob(id,true),pollInterval*2);}}}
 async function refresh(){if(busy||!current())return;setBusy(true);try{const value=await client.request('/document-translations');jobs=Array.isArray(value.items)?value.items:[];renderJobs();state('任务列表已更新。');if(selected)await openJob(selected.id);}catch(error){if(current()&&error.name!=='AbortError')state(error.message,true);}finally{if(current())setBusy(false);}}
 async function prepareQuote(){
  if(!current()||busy)return;const serial=quoteVersion,accountFile=$('[data-doc-file]').value,file=$('[data-doc-upload]').files?.[0],sourceLanguage=$('[data-doc-source]').value,targetLanguage=$('[data-doc-target]').value;if(!accountFile&&!file)return;if(sourceLanguage===targetLanguage){$('[data-doc-billing]').textContent='原文语言与目标语言不能相同。';return;}
  try{if(accountFile){const existing=files.find(row=>row.id===accountFile);if(!existing)throw Error('所选原件已不存在，请刷新后重试。');validateTranslationFile({name:existing.name,size:Number(existing.bytes)},cap);}else validateTranslationFile(file,cap);
   setBusy(true);$('[data-doc-billing]').textContent=accountFile?'正在核对本次费用…':'正在保存原件并核对本次费用…';const latest=await client.request('/auth/me');if(latest.user?.id!==session.user.id)throw Error('登录账户已变化，请重新打开。');let fileId=accountFile;
   if(!fileId){if(!uploaded){const saved=await reuseStoredOriginal(file,{api:(path,body)=>client.request(path,body,{timeout:120000}),expectedUserId:session.user.id})||await client.request('/files',{name:file.name,data:await fileBase64(file),expectedUserId:session.user.id},{timeout:120000});if(!saved.id)throw Error('原件保存未完成，请重试。');if(!current()||serial!==quoteVersion)return;uploaded=saved.id;files.unshift({...saved,name:file.name,bytes:file.size});}fileId=uploaded;}
   const input={fileId,sourceLanguage,targetLanguage,expectedUserId:session.user.id},quote=await client.request('/document-translations/quote',input,{timeout:60000});if(!current()||serial!==quoteVersion)return;if(!quote.existingJobId&&!validServiceQuote(quote,'agent'))throw Error('暂时无法确认费用，请稍后重试。');preparedQuote=quote;quoteInput=JSON.stringify(input);clearTimeout(quoteExpiry);if(!quote.existingJobId)quoteExpiry=setTimeout(()=>{if(current()&&preparedQuote===quote){preparedQuote=null;quoteInput='';$('[data-doc-billing]').textContent='费用已过期，正在重新核对…';void prepareQuote();}},Math.min(Math.max(1,Date.parse(quote.expiresAt)-Date.now()+1),2147483647));$('[data-doc-billing]').textContent=quote.existingJobId?'已有译文，查看结果不重复扣费。':billingQuoteLabel(quote)+' · 成功后结算，失败或取消释放预占';
  }catch(error){if(current()&&serial===quoteVersion)$('[data-doc-billing]').textContent=serviceMessage(error.message||'费用暂不可用，请重试。');}finally{if(current()){setBusy(false);if(serial!==quoteVersion)void prepareQuote();}}
 }
 async function submit(){if(busy)return;const accountFile=$('[data-doc-file]').value,sourceLanguage=$('[data-doc-source]').value,targetLanguage=$('[data-doc-target]').value,input={fileId:accountFile||uploaded,sourceLanguage,targetLanguage,expectedUserId:session.user.id},quote=preparedQuote;
  if(!input.fileId||quoteInput!==JSON.stringify(input)||!quote||!quote.existingJobId&&!validServiceQuote(quote,'agent')){state('请等待本次费用显示后开始翻译。',true);void prepareQuote();return;}
  submitting=true;flowError='';flowMessage='正在提交翻译…';errorStep=3;setBusy(true);clearTimeout(timer);try{const latest=await client.request('/auth/me');if(latest.user?.id!==session.user.id)throw Error('登录账户已变化，请关闭窗口后重新打开。');let id=quote.existingJobId;if(!id){const result=await client.request('/document-translations',{...input,idempotencyKey:requestKey,consent:true,billingToken:quote.token},{timeout:60000});id=result.id;}if(!id)throw Error('未取得任务编号，请刷新任务列表核对，无需重复提交。');preparedQuote=null;quoteInput='';requestKey=uuid();await openJob(id);notify('文档翻译已提交，可在此查看进度。');}catch(error){if(current()&&error.name!=='AbortError')state(error.message,true);}finally{submitting=false;if(current()){setBusy(false);schedule();}}}
 const ready=(async()=>{container.innerHTML='<p class="document-service-loading" role="status">正在读取账户与文档翻译服务…</p>';try{const [me,capabilities]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);session=me;cap=capabilities.documentTranslation||{};if(!me.user?.id){container.innerHTML=`<div class="document-service-empty"><h3>登录后翻译整篇文档</h3><p>原件与译文按账户私有保存，任务可稍后继续查看。</p><a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a></div>`;return;}if(!cap.ready){container.innerHTML='<div class="document-service-empty"><h3>整篇文档翻译暂未开放</h3><p>请稍后重试。你仍可使用“原文对照翻译”处理已导入的文本。</p></div>';return;}const [fileList,jobList]=await Promise.all([client.request('/files'),client.request('/document-translations')]);files=eligibleTranslationFiles(fileList.items);jobs=Array.isArray(jobList.items)?jobList.items:[];render();const active=jobs.find(job=>!terminal(job.status));if(active)await openJob(active.id);}catch(error){if(current()&&error.name!=='AbortError')container.innerHTML=`<div class="document-service-empty"><p role="alert">${esc(error.status===401?'请登录后再使用整篇文档翻译。':serviceMessage(error.message))}</p>${error.status===401?`<a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a>`:''}</div>`;}})();
 return {ready,dispose};
}
